class Solution { private fun between(value:Int,left:Int,right:Int)=minOf(left,right)<value&&value<maxOf(left,right);fun minMovesToCaptureTheQueen(a:Int,b:Int,c:Int,d:Int,e:Int,f:Int):Int{if(a==e&&!(c==a&&between(d,b,f)))return 1;if(b==f&&!(d==b&&between(c,a,e)))return 1;if(kotlin.math.abs(c-e)==kotlin.math.abs(d-f)){val blocked=kotlin.math.abs(a-c)==kotlin.math.abs(b-d)&&between(a,c,e)&&between(b,d,f);if(!blocked)return 1};return 2} }
